#include <cmath>
class Complexe {
public:
  Complexe(double r, double i) : real_{ r }, imag_{ i } {}
  double module() { return std::sqrt(real_ * real_ + imag_ * imag_); }
private:
  double real_, imag_;
};
double print(const Complexe& c) { return c.module(); }
int main() { return print(Complexe{ 3, 4 }) == 5 ? 0 : 1; }

